/**                                                                       */
/** ThreadX Test                                                          */
/**                                                                       */
/**   Module Manager host test port shim                                  */
/**                                                                       */
/**************************************************************************/
/**************************************************************************/

/* The Module Manager is not in the ThreadX library this test tree builds, and its
   control blocks come from a module port rather than a base port, so the manager
   sources under test are compiled directly against one module port's headers. Every
   module port is an embedded architecture, and their interrupt primitives are
   inline assembly for that architecture, which the host assembler cannot take.

   This header is force-included ahead of each manager source under test. It brings
   the port's headers in first, so every declaration the source needs is the port's
   own, and then replaces the three interrupt primitives with host equivalents that
   count instead of executing. Counting is not only what makes them portable: a test
   can assert that a source under test left the interrupt lock balanced, and that a
   section which has to run with interrupts disabled did so.  */

#ifndef THREADX_MODULE_MANAGER_HOST_TEST_PORT_H
#define THREADX_MODULE_MANAGER_HOST_TEST_PORT_H

#define TX_SOURCE_CODE

#include "tx_api.h"

#undef TX_INTERRUPT_SAVE_AREA
#undef TX_DISABLE
#undef TX_RESTORE

/* Nesting depth of the stand-in interrupt lock, and the deepest it has ever been.
   Defined by the test, which is the only translation unit that reads them.  */
extern unsigned int test_interrupt_disable_depth;
extern unsigned int test_interrupt_disable_max_depth;
extern unsigned int test_interrupt_restore_underflows;

#define TX_INTERRUPT_SAVE_AREA

#define TX_DISABLE                                                          \
    {                                                                       \
        test_interrupt_disable_depth++;                                     \
        if (test_interrupt_disable_depth > test_interrupt_disable_max_depth) \
        {                                                                   \
            test_interrupt_disable_max_depth = test_interrupt_disable_depth; \
        }                                                                   \
    }

#define TX_RESTORE                                                          \
    {                                                                       \
        if (test_interrupt_disable_depth == 0U)                             \
        {                                                                   \
            test_interrupt_restore_underflows++;                            \
        }                                                                   \
        else                                                                \
        {                                                                   \
            test_interrupt_disable_depth--;                                 \
        }                                                                   \
    }

#endif
